import time
from collections import OrderedDict


class Cache:
    """LRU cache with per-entry time-to-live."""

    def __init__(self, capacity, ttl_seconds, now=time.monotonic):
        self.capacity = capacity
        self.ttl_seconds = ttl_seconds
        self.now = now
        self._store = OrderedDict()  # key -> (value, insert_time)

    def _expired(self, timestamp):
        return self.now() - timestamp >= self.ttl_seconds

    def _purge_expired(self):
        """Remove every expired entry."""
        expired = [k for k, (_, ts) in self._store.items() if self._expired(ts)]
        for k in expired:
            del self._store[k]

    def put(self, key, value):
        if key in self._store:
            # Update: reset TTL and promote to most-recently-used.
            self._store[key] = (value, self.now())
            self._store.move_to_end(key)
        elif self.capacity > 0:
            # New key: drop all expired entries first.
            self._purge_expired()
            # If still at capacity, evict the LRU (first) live entry.
            while len(self._store) >= self.capacity:
                self._store.popitem(last=False)
            self._store[key] = (value, self.now())

    def get(self, key):
        if key not in self._store:
            return None
        value, ts = self._store[key]
        if self._expired(ts):
            # Expired: remove without touching recency ordering.
            del self._store[key]
            return None
        # Live: promote to most-recently-used.
        self._store.move_to_end(key)
        return value

    def __len__(self):
        return sum(1 for _, (_, ts) in self._store.items() if not self._expired(ts))

    def keys(self):
        return [k for k, (_, ts) in self._store.items() if not self._expired(ts)]

